import { relations } from "drizzle-orm";
import {
  index,
  integer,
  pgTable,
  timestamp,
  varchar,
} from "drizzle-orm/pg-core";
import { companyAlias } from "./company-alias";

/*
CREATE TABLE "company_name" (
    "pk"              integer                  GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "alias_pk"        integer                  NOT NULL REFERENCES "company_alias" ("pk"),
    "name"            varchar(128)             NOT NULL,
    "normalized_name" varchar(128)             NOT NULL UNIQUE,
    "created_at"      timestamp with time zone NOT NULL DEFAULT NOW()
);
CREATE INDEX ON "company_name" ("alias_pk");
CREATE INDEX ON "company_name" USING gin ("normalized_name" gin_trgm_ops);
*/
// 회사 이름 표기. 회사 검색은 이 테이블만 봄 (alias 이름도 여기에 들어 있음)
// 한 표기는 한 회사에만 속함 (normalized_name UNIQUE)
export const companyName = pgTable(
  "company_name",
  {
    pk: integer("pk").primaryKey().generatedByDefaultAsIdentity().notNull(),
    aliasPk: integer("alias_pk")
      .notNull()
      .references(() => companyAlias.pk),
    // 입력된 원문
    name: varchar("name", { length: 128 }).notNull(),
    // normalizeCompanyName(name). 검색 · 중복 판단용
    normalizedName: varchar("normalized_name", { length: 128 })
      .notNull()
      .unique(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    index().on(table.aliasPk),
    // LIKE '%q%' 부분 일치 검색 (pg_trgm)
    index("company_name_normalized_name_trgm_idx").using(
      "gin",
      table.normalizedName.op("gin_trgm_ops"),
    ),
  ],
);

export const companyNameRelations = relations(companyName, ({ one }) => ({
  alias: one(companyAlias, {
    fields: [companyName.aliasPk],
    references: [companyAlias.pk],
  }),
}));
